<script>
window.addEventListener('load',function(){var modal=$('#consultationFeeModal'),form=$('#consultationFeeForm');$(document).on('click.consultationFee','.js-consultation-fee',function(){var b=$(this);form.attr('action','<?= esc($feeEndpoint ?? '', 'js') ?>'.replace(/\/$/,'')+'/'+b.data('appointment-id'));$('#consultationFeeAppointment').text(b.data('appointment-number')||'—');$('#consultationFeeAmount').val(b.data('amount')||'');$('#consultationFeeIdempotency').val('consultation-fee-'+b.data('appointment-id')+'-'+Date.now()+'-'+Math.random().toString(16).slice(2));modal.modal('show');});form.on('submit',function(e){e.preventDefault();var submit=form.find('[type=submit]').prop('disabled',true);ajaxRequest({url:form.attr('action'),method:'POST',data:form.serialize(),success:function(r){if(r.status){modal.modal('hide');window.location.reload();}else{showError(r.msg||'Payment could not be recorded.');}},error:function(xhr){var r=xhr.responseJSON||{};showError(r.msg||'Payment could not be recorded.');},complete:function(){submit.prop('disabled',false);}});});});
</script>
